parameters.jsCode:
const caseId = $('Get Case Info').first().json['Case ID'] ;

// 1. Perform your math once and store as strings
const deposited   = Number($('Update Deposit: Sufficient').first().json['Deposited Fund'] || 0);  
const fee         = Number($('Get Case Info').first().json.Fee || 0);
const escrowFund  = Number($('Get Case Info').first().json['Escrow Fund'] || 0);

const transferred = Number($('Get Case Info').first().json['Payment to Seller'] || 0) + 
                    Number($('Get Case Info').first().json['Refund to Buyer'] || 0);

const totalRequired = escrowFund + fee; 

// Ensure excess is either a positive number or zero (no negatives)
const excessWei     = Math.max(0, deposited - totalRequired); 
const excessEth     = excessWei > 0 ? (excessWei / 1e18) : "0"; 

// Calculate remaining balance in Escrow
const escrowBalance = Math.max(0, escrowFund - transferred); 
const escrowEth     = escrowBalance > 0 ? (escrowBalance / 1e18) : "0"; 

// 2. Check the condition
const sellerResponse = $('Get Case Info').first().json['Seller Response'] ; 
const buyerResponse = $('Get Case Info').first().json['Buyer Response'] ;

const isEffective = (sellerResponse === 'accept' && buyerResponse === 'accept' && deposited >= totalRequired);

const buyerToken = $('Get Case Info').first().json['Buyer Token'];
const sellerToken = $('Get Case Info').first().json['Seller Token'];

const base = $vars.BASE_URL; // e.g., https://blockcenter.app.n8n.cloud/

// Append '-test' unless the workflow is officially active in production
const webhookPath = 'webhook' + ($execution.mode === 'production' ? '' : '-test');
const formPath    = 'form'    + ($execution.mode === 'production' ? '' : '-test');

// 3. Generate the URLs dynamically
const requestUrl = `${base}${webhookPath}/request?caseId=${caseId}&amountETH=${escrowEth}`;
const excessUrl  = `${base}${formPath}/excess?caseId=${caseId}&token=${buyerToken}`;

const paymentUrl = `${base}${formPath}/payment?caseId=${caseId}&amountETH=${escrowEth}&token=${buyerToken}`;
const refundUrl  = `${base}${formPath}/refund?caseId=${caseId}&amountETH=${escrowEth}&token=${sellerToken}`;

// const baseUrlW = $('Deposit Fund').first().json.webhookUrl; // webhook
// const baseUrlF = baseUrlW.replace('/webhook', '/form');

// const requestUrl = `${baseUrlW.replace('/deposit', '/request')}?caseId=${caseId}`;
// const excessUrl = `${baseUrlF.replace('/deposit', '/excess')}?caseId=${caseId}&token=${buyerToken}`;

// const paymentUrl = `${baseUrlF.replace('/deposit', '/release')}?caseId=${caseId}`;
// const refundUrl = `${baseUrlF.replace('/deposit', '/refund')}?caseId=${caseId}`;

// 3. Define the HTML blocks (or leave empty if condition fails)

let buyerHtml = "", sellerHtml = "";

if (isEffective) {
buyerHtml = `
<div style="font-family: sans-serif; max-width: 600px; margin: auto;">

    <div style="padding: 25px; background-color: #f8fbff; border: 1px solid #d0e3ff; border-radius: 10px; text-align: center;">
        <h4 style="margin: 0 0 15px 0; color: #0056b3;">Contract Status: Effective</h4>

        <a href="${paymentUrl}" 
           style="display: block; background-color: #28a745; color: #ffffff; padding: 16px; border-radius: 8px; text-decoration: none; font-weight: bold; font-size: 16px; margin-bottom: 15px;">Release Payment to Seller
        </a>

        <p style="font-size: 13px; color: #666;">
            Problem with the deal? <a href="${requestUrl}&token=${buyerToken}" style="color: #cb2431; text-decoration: underline;">Request a Refund</a>
        </p>
    </div>

    ${excessWei > 0 ? ` 
    <div style="margin-top: 20px; padding: 15px; background-color: #fff9e6; border: 1px solid #ffeeba; border-radius: 10px;">
        <p style="margin: 0 0 10px 0; font-size: 14px; color: #856404; text-align: center;">
            <b>Extra Balance</b> : <b>${excessEth} ETH</b> 
        </p>
        <div style="text-align: center;">
            <a href="${excessUrl}&action=tip" style="color: #28a745; font-weight: bold; font-size: 13px; text-decoration: none; margin-right: 20px;">🎁 Send as Tip</a>
            <a href="${excessUrl}&action=withdraw" style="color: #856404; font-weight: bold; font-size: 13px; text-decoration: none;">💰 Withdraw to Wallet</a>
        </div>
    </div>
    ` : ""}

</div>
`;


sellerHtml = `
    <div style="background:#f8fbff; border:1px solid #d0e3ff; padding:20px; border-radius:10px; text-align:center;">
        <h4 style="margin-top:0;">Contract is now Effective</h4>
        <table width="100%"><tr>
            <td width="50%"><a href="${refundUrl}" style="background:#6c757d; color:#fff; padding:12px; display:block; border-radius:6px; text-decoration:none; font-weight:bold;">Send Refund</a></td>
            <td width="10"></td>
            <td width="50%"><a href="${requestUrl}&token=${sellerToken}" style="background:#0366d6; color:#fff; padding:12px; display:block; border-radius:6px; text-decoration:none; font-weight:bold;">Request Payment</a></td>
        </tr></table>
    </div>`;
}

// 4. Return everything to use in the Email nodes
return {
  caseId,
  sellerResponse,
  buyerResponse, 
  totalRequired, 
  deposited,
  transferred, 
  buyerHtml, 
  sellerHtml
};

