const item = $input.first();

// 1. Calculate Balance & Escrow (as BigInt)
const balance = BigInt(item.json['Deposited Fund'] || 0) - 
             BigInt(item.json.Fee || 0) - 
             BigInt(item.json['Tip to Seller'] || 0) - 
             BigInt(item.json['Buyer Withdrawal'] || 0) - 
             BigInt(item.json['Payment to Seller'] || 0) - 
             BigInt(item.json['Refund to Buyer'] || 0);

const escrow = BigInt(item.json['Escrow Fund'] || 0) - 
             BigInt(item.json['Payment to Seller'] || 0) - 
             BigInt(item.json['Refund to Buyer'] || 0);

// 2. Safely get Amount
const rawAmount = $('Pay Seller').isExecuted ? $('Pay Seller').first().json.amountETH : ($('Refund Buyer').isExecuted ? $('Refund Buyer').first().json.amountETH : "0");
const amountETH = String(rawAmount || "0");

// 3. Manual parseEther (String-based to avoid float errors)
function parseToWei(eth) {
    let [whole, fraction = ""] = eth.split(".");
    fraction = fraction.slice(0, 18).padEnd(18, "0");
    return BigInt(whole + fraction);
}

const amountWei = parseToWei(amountETH);

// 4. Choose the smaller value
const remittance = amountWei < escrow ? amountWei : escrow;

// 5. Return (Convert BigInt to String for n8n JSON)
return {
  balance: balance.toString(),
  escrow: escrow.toString(), 
  amountETH,
  amountWei: amountWei.toString(),
  remittance: remittance.toString()
};

